  "inlineSchema": "// =============================================================\n//  Esquema de base de datos - App de transporte (tipo Uber/InDrive)\n// =============================================================\n\ngenerator client {\n  provider            = \"prisma-client\"\n  output              = \"../src/generated/prisma\"\n  moduleFormat        = \"esm\"\n  importFileExtension = \"js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------- Enums ----------\n\nenum Role {\n  PASSENGER\n  DRIVER\n  ADMIN\n}\n\nenum DriverStatus {\n  PENDING // registrado, esperando aprobación del admin\n  APPROVED\n  REJECTED\n  SUSPENDED\n}\n\nenum VehicleType {\n  CAR\n  MOTO\n}\n\nenum PricingMode {\n  FIXED // tarifa calculada (estilo Uber)\n  BIDDING // pasajero propone precio, conductores ofertan (estilo InDrive)\n}\n\nenum TripStatus {\n  REQUESTED // buscando conductor\n  ACCEPTED // conductor asignado, en camino al punto de recogida\n  ARRIVED // conductor llegó al punto de recogida\n  IN_PROGRESS // viaje en curso\n  COMPLETED\n  CANCELLED\n}\n\nenum OfferStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  EXPIRED\n}\n\nenum PaymentMethod {\n  CASH\n  CARD\n  WALLET\n}\n\n// ---------- Modelos ----------\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  phone        String   @unique\n  email        String?  @unique\n  passwordHash String\n  role         Role     @default(PASSENGER)\n  isActive     Boolean  @default(true)\n  avatarUrl    String?\n  rating       Float    @default(5)\n  ratingCount  Int      @default(0)\n  fcmToken     String? // token para notificaciones push\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  driver Driver?\n  trips  Trip[]  @relation(\"PassengerTrips\")\n\n  @@index([role])\n}\n\nmodel Driver {\n  id            String       @id @default(uuid())\n  userId        String       @unique\n  user          User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  status        DriverStatus @default(PENDING)\n  licenseNumber String\n  isOnline      Boolean      @default(false)\n  lastLat       Float?\n  lastLng       Float?\n  lastSeenAt    DateTime?\n  totalTrips    Int          @default(0)\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  vehicle Vehicle?\n  trips   Trip[]\n  offers  TripOffer[]\n\n  @@index([status, isOnline])\n}\n\nmodel Vehicle {\n  id       String      @id @default(uuid())\n  driverId String      @unique\n  driver   Driver      @relation(fields: [driverId], references: [id], onDelete: Cascade)\n  type     VehicleType @default(CAR)\n  brand    String\n  model    String\n  color    String\n  plate    String      @unique\n  year     Int\n}\n\nmodel Trip {\n  id          String        @id @default(uuid())\n  passengerId String\n  passenger   User          @relation(\"PassengerTrips\", fields: [passengerId], references: [id])\n  driverId    String?\n  driver      Driver?       @relation(fields: [driverId], references: [id])\n  status      TripStatus    @default(REQUESTED)\n  pricingMode PricingMode   @default(FIXED)\n  vehicleType VehicleType   @default(CAR)\n  payment     PaymentMethod @default(CASH)\n\n  originLat     Float\n  originLng     Float\n  originAddress String\n  destLat       Float\n  destLng       Float\n  destAddress   String\n  polyline      String? // ruta codificada (Google encoded polyline)\n\n  distanceMeters  Int\n  durationSeconds Int\n  estimatedFare   Decimal  @db.Decimal(10, 2)\n  proposedFare    Decimal? @db.Decimal(10, 2) // precio propuesto por el pasajero (BIDDING)\n  finalFare       Decimal? @db.Decimal(10, 2)\n  currency        String   @default(\"USD\")\n\n  requestedAt  DateTime  @default(now())\n  acceptedAt   DateTime?\n  arrivedAt    DateTime?\n  startedAt    DateTime?\n  completedAt  DateTime?\n  cancelledAt  DateTime?\n  cancelledBy  Role?\n  cancelReason String?\n\n  ratingByPassenger Int? // calificación que el pasajero da al conductor\n  ratingByDriver    Int? // calificación que el conductor da al pasajero\n\n  offers TripOffer[]\n\n  @@index([status])\n  @@index([passengerId, status])\n  @@index([driverId, status])\n}\n\nmodel TripOffer {\n  id         String      @id @default(uuid())\n  tripId     String\n  trip       Trip        @relation(fields: [tripId], references: [id], onDelete: Cascade)\n  driverId   String\n  driver     Driver      @relation(fields: [driverId], references: [id])\n  amount     Decimal     @db.Decimal(10, 2)\n  etaSeconds Int?\n  status     OfferStatus @default(PENDING)\n  createdAt  DateTime    @default(now())\n\n  @@unique([tripId, driverId])\n}\n\n/// Tarifas configurables desde el panel admin, una por tipo de vehículo\nmodel FareSetting {\n  id             String      @id @default(uuid())\n  vehicleType    VehicleType @unique\n  baseFare       Decimal     @db.Decimal(10, 2)\n  perKm          Decimal     @db.Decimal(10, 2)\n  perMinute      Decimal     @db.Decimal(10, 2)\n  minimumFare    Decimal     @db.Decimal(10, 2)\n  bookingFee     Decimal     @default(0) @db.Decimal(10, 2)\n  currency       String      @default(\"USD\")\n  biddingEnabled Boolean     @default(true)\n  /// el pasajero no puede ofertar menos de este % de la tarifa estimada\n  minBidPercent  Int         @default(70)\n  /// comisión de la plataforma en %\n  commissionPct  Int         @default(10)\n  updatedAt      DateTime    @updatedAt\n}\n",
